query:
SELECT * FROM (
  SELECT c.contact_id AS id, COALESCE(c.kode, '') AS code, COALESCE(c.perusahaan, '') AS name,
         c.is_customer, c.is_employee
  FROM cardfile c
) G1
WHERE 1=1 {andWhere}
ORDER BY G1.NAME, G1.CODE {andOrder} {limit}

